/*
 * presets.h
 *
 * FDA mode: the operator presets are baked into the image and the firmware --
 * not the host -- programs the TX7332 chips from them. The host picks one by
 * index with OW_PRESET_LOAD; host register writes are refused.
 *
 * Each preset is {address, value} tables, exactly like the reg_values tables
 * in demo.c, generated by the openlifu SDK and committed under
 * Core/Inc/presets/<set>/. Loading one just iterates and writes. The build
 * needs no Python and no SDK.
 *
 * Two CRC-32s (IEEE, zlib-compatible) travel with every preset so the host can
 * prove what it is about to run:
 *   settings_crc  over the raw preset .json the SDK generated from -- the host
 *                 hashes its own copy of the file and compares.
 *   regs_crc      over the register tables (PRESET_CRC_STREAM below). Baked by
 *                 the SDK, recomputed here from flash on every request, and
 *                 required in OW_PRESET_LOAD: a load with the wrong value is
 *                 refused, so host and image can never disagree about what
 *                 preset N programs.
 *
 * Nothing here exists unless the image is built with FDA_MODE.
 */

#ifndef INC_PRESETS_H_
#define INC_PRESETS_H_

#ifdef FDA_MODE

#include "tx7332.h"

#include <stdbool.h>
#include <stdint.h>

#define ARRAY_COUNT(a) (sizeof(a) / sizeof((a)[0]))

// Largest id the generator will emit, so the OW_PRESET_GET reply stays bounded.
#define PRESET_ID_MAX 64u

// A run of {address, value} pairs to write in order, as in demo.c.
typedef struct {
	const uint32_t (*regs)[2];
	uint16_t count;
} PresetRegList;

typedef struct {
	const char *id;
	const PresetRegList *base;         // one per chip
	const PresetRegList *profile_regs; // chip-major: [chip * profile_count + profile]
	const uint8_t *exec_order;
	uint8_t chip_count;
	uint8_t profile_count;
	uint8_t profile_index;             // profile active before the first trigger (1-based)
	uint8_t exec_order_len;
	// Trigger timing the preset defines. Run length is not here: it arrives
	// with OW_PRESET_LOAD, because it is how long to run rather than preset data.
	uint32_t trig_frequency_hz;
	uint32_t trig_pulse_count;
	uint32_t trig_train_interval_us;
	uint32_t settings_crc;             // CRC-32 of the source .json bytes
	uint32_t regs_crc;                 // CRC-32 of PRESET_CRC_STREAM, as generated
} Preset;

/*
 * PRESET_CRC_STREAM -- the bytes regs_crc covers, little-endian, in order.
 * The SDK generator and presets_regs_crc() must walk this identically.
 *
 *   u8  chip_count, u8 profile_count, u8 profile_index, u8 exec_order_len
 *   u8  exec_order[exec_order_len]
 *   u32 trig_frequency_hz, u32 trig_pulse_count, u32 trig_train_interval_us
 *   per chip:
 *     u16 base count, then (u16 addr, u32 value) per pair
 *     per profile: u16 count, then (u16 addr, u32 value) per pair
 */

// Width of the trigger line marker pulse. Not the acoustic burst -- that
// length is already in the pattern registers the preset carries.
#define PRESET_TRIGGER_PULSE_WIDTH_US 20u

/** Number of presets baked into this image. */
uint8_t presets_count(void);

/** Preset at index, or NULL if out of range. */
const Preset *presets_get(uint8_t index);

/**
 * @brief  CRC-32 over a preset's register tables, computed from flash now.
 *
 * Equal to preset->regs_crc unless the image is inconsistent with what the
 * generator produced; callers treat a mismatch as a refused preset.
 */
uint32_t presets_regs_crc(const Preset *preset);

/**
 * @brief  Program this module's TX7332 chips from a baked preset.
 *
 * Refused unless expected_regs_crc equals the CRC computed from flash, so a
 * host that holds a different idea of preset N cannot run it. Writes the base
 * registers, installs the execution order so the trigger ISRs can cycle
 * profiles, applies the preset's trigger timing, and activates its starting
 * profile.
 *
 * @param train_count       how many pulse trains to run; 0 keeps the current value.
 * @param expected_regs_crc the regs_crc the host computed for this preset.
 * @return true on success; false on a bad index, a CRC mismatch, or if a
 *         trigger is running.
 */
bool presets_load(uint8_t index, uint32_t train_count, uint32_t expected_regs_crc);

#endif /* FDA_MODE */

#endif /* INC_PRESETS_H_ */
